/* Catálogo multissegmento e encomendas com vários itens. */
const checkoutStages=['Definição','Tamanho','Recheios','Sabores','Personalização','Detalhes','Perguntas','Agendamento','Revisão','Finalização'];
let productClassFilter='';
function productClassField(selected){return `<div class="field-group"><label for="product-class">Classe do produto</label><select id="product-class" class="field" name="productClass"><option value="">Sem classe</option>${(db.productClasses||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small>Cadastre as classes no botão Classes de produto, na tela Produtos.</small></div>`}
function productClassToolbar(){if(productClassFilter&&productClassFilter!=='__unclassified'&&!(db.productClasses||[]).some(c=>c.id===productClassFilter))productClassFilter='';return `<div class="toolbar product-class-toolbar"><label for="product-class-filter">Filtrar por classe</label><select id="product-class-filter" class="field" onchange="productClassFilter=this.value;render()"><option value="">Todas as classes</option><option value="__unclassified" ${productClassFilter==='__unclassified'?'selected':''}>Sem classe</option>${(db.productClasses||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===productClassFilter?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="muted">${filteredClassProducts().length} produto(s)</span></div>`}
function filteredClassProducts(){return db.products.filter(p=>!productClassFilter||(productClassFilter==='__unclassified'?!p.classId:p.classId===productClassFilter))}
function productClassBadge(p){const c=(db.productClasses||[]).find(c=>c.id===p.classId);return c?`<span class="product-class-badge">${esc(c.name)}</span>`:''}
function productClassesModal(){modal(`<div class="dialog-head"><h2>Classes de produto</h2><button onclick="$('#modal').close()">✕</button></div><p>Organize seus produtos por grupos, como Bolos, Doces ou Personalizados.</p><button class="primary" onclick="editProductClass()">+ Cadastrar classe</button><div class="product-class-list">${(db.productClasses||[]).map(c=>`<section class="cart-line"><h3>${esc(c.name)}</h3><p>${db.products.filter(p=>p.classId===c.id).length} produto(s)</p><div class="dialog-actions"><button class="plain" onclick="editProductClass('${c.id}')">Editar</button><button class="plain" onclick="confirmDeleteProductClass('${c.id}')">Excluir</button></div></section>`).join('')||'<p class="muted">Nenhuma classe cadastrada.</p>'}</div>`)}
function editProductClass(id){const c=(db.productClasses||[]).find(c=>c.id===id);modal(`<div class="dialog-head"><h2>${c?'Editar':'Cadastrar'} classe de produto</h2><button onclick="productClassesModal()">Voltar</button></div><form onsubmit="saveProductClass(event,'${id||''}')"><div class="field-group"><label>Nome da classe</label><input name="className" required maxlength="100" placeholder="Ex.: Bolos" value="${esc(c?.name||'')}"></div><button class="primary">Salvar classe</button></form>`)}
async function saveProductClass(e,id){e.preventDefault();await submitForm(e.target,async()=>{const name=e.target.elements.className.value.trim(),classes=db.productClasses||[];if(classes.some(c=>c.id!==id&&c.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')))throw Error('Já existe uma classe com esse nome');if(id&&!classes.some(c=>c.id===id))throw Error('Classe não encontrada');const c={id:id||crypto.randomUUID(),name};await persistTenant({...db,productClasses:id?classes.map(row=>row.id===id?c:row):[...classes,c]});render();productClassesModal();toast('Classe salva')})}
function confirmDeleteProductClass(id){const c=(db.productClasses||[]).find(c=>c.id===id);if(!c)return;modal(`<h2>Excluir a classe ${esc(c.name)}?</h2><p>Os produtos serão mantidos e ficarão sem classe.</p><div class="dialog-actions"><button class="plain" onclick="productClassesModal()">Voltar</button><button class="primary" onclick="deleteProductClass('${c.id}')">Excluir classe</button></div>`)}
async function deleteProductClass(id){try{await persistTenant({...db,productClasses:(db.productClasses||[]).filter(c=>c.id!==id),products:db.products.map(p=>p.classId===id?{...p,classId:''}:p)});if(productClassFilter===id)productClassFilter='';render();productClassesModal();toast('Classe excluída; produtos mantidos')}catch(e){toast(e.message)}}
function descendingCakeSizes(p){const sizes=productSizes(p),diameter=s=>/^\s*(\d+(?:[.,]\d+)?)\s*cm\b/i.exec(s.name);return sizes.length&&sizes.every(s=>diameter(s))?[...sizes].sort((a,b)=>Number(diameter(b)[1].replace(',','.'))-Number(diameter(a)[1].replace(',','.'))):[...sizes]}
function openProductSizes(id){const p=db.products.find(p=>String(p.id)===id);if(!p)return;if(productConfig(p).sizes?.length){configureProduct(id);const field=$('#modal textarea[name="sizes"]');field?.scrollIntoView?.({block:'center'});field?.focus?.()}else openSharedPrices(id)}
function sizeChoice(p,v){const c=productConfig(p);return `<div class="field-group"><label>Tamanho</label><select class="field" name="size" onchange="itemDraft.size=this.value;updateItemSubtotal()">${descendingCakeSizes(p).map(s=>`<option value="${esc(s.id)}" ${s.id===v.size?'selected':''}>${esc(s.name)} · ${esc(s.serves)} · ${money(c.type==='cake'?s.price+p.price-(db.rules.reference??65):s.price)}</option>`).join('')}</select></div>`}
function instructionBlock(stage){const text=db.commerce?.instructions?.[stage];return text?`<p class="note preserve-lines">${esc(text)}</p>`:''}
function updateItemSubtotal(){const value=$('.item-config .total strong');if(value&&itemDraft)value.textContent=money(cartLineValue(itemDraft))}
function readCheckoutFields(f){for(const [field,key] of Object.entries({customerName:'name',customerPhone:'customerPhone',delivery:'delivery',pickupTime:'pickupTime',notes:'notes',birthDate:'birthDate',fulfillment:'fulfillment',address:'address',eventName:'eventName',eventType:'eventType',eventDate:'eventDate'}))if(f[field])checkoutDraft[key]=f[field].value;if(f.marketingConsent)checkoutDraft.marketingConsent=f.marketingConsent.checked}
function validateCheckoutDraft(){if(!checkoutDraft.name?.trim())throw Error('Informe seu nome');checkoutDraft.customerPhone=normalizeBrazilPhone(checkoutDraft.customerPhone);if(!checkoutDraft.delivery||checkoutDraft.delivery<minimumDelivery()||isDeliveryBlocked(checkoutDraft.delivery))throw Error('Escolha uma data disponível para entrega.');const time=checkoutDraft.pickupTime;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time||'')||time<(db.commerce?.openTime||'08:00')||time>(db.commerce?.closeTime||'18:00'))throw Error('Escolha um horário dentro do atendimento da loja');if(checkoutDraft.fulfillment==='delivery'&&(db.commerce?.serviceMode==='pickup'||!checkoutDraft.address?.trim()))throw Error('Confira a modalidade e o endereço de entrega')}
function fillingLimit(p){const c=productConfig(p);return c.max_selected===undefined?6:Math.min(30,(c.included??db.rules.included)+c.max_selected)}
function fillingAmount(p,name,size){const c=productConfig(p);return db.fillingSettings?.[name]?.hasAdditional===false?0:c.fillingOptions?.[name]?.bySize?.[size]??c.fillingOptions?.[name]?.price??db.fillingPrices?.[name]??0}
function fillingChoices(p,v){const c=productConfig(p),extra=c.extraBySize?.[v.size]??c.extra??db.rules.extra;return ((c.quantityExtraEnabled??db.rules.quantityExtraEnabled)===false?'':`<p>${money(extra)} por recheio excedente.</p>`)+db.fillings.filter(f=>db.fillingSettings?.[f]?.active!==false&&c.fillingOptions?.[f]?.enabled!==false).map((f,i)=>`<label class="commerce-option"><input type="checkbox" style="width:auto" name="fill" value="${esc(f)}" ${v.fill.includes(f)?'checked':''} ${db.fillingSettings?.[f]?.available===false?'disabled':''}> ${esc(f)} ${db.fillingSettings?.[f]?.available===false?'· Indisponível':fillingAmount(p,f,v.size)?' + '+money(fillingAmount(p,f,v.size)):''}</label>`).join('')}
function productStatusControls(p){return `<div class="product-status-controls"><button class="plain" onclick="toggleProductStatus('${p.id}','active')">${p.active===false?'Inativo · ativar':'Ativo · desativar'}</button><button class="soft" onclick="toggleProductStatus('${p.id}','available')">${p.available===false?'Indisponível · liberar':'Disponível · pausar'}</button></div>`}
async function toggleProductStatus(id,key){try{await persistTenant({...db,products:db.products.map(p=>String(p.id)===id?{...p,[key]:p[key]===false}:p)});render();toast('Status atualizado na loja')}catch(e){toast(e.message)}}
function fillingsPage(){return heading('Recheios','Cadastre adicionais e controle a disponibilidade.',`<button class="primary" onclick="editFilling(-1)">+ Cadastrar recheio</button>`)+`<div class="theme-admin-list">${db.fillings.map((f,i)=>`<section class="card"><h2>${esc(f)}</h2><p>${db.fillingSettings?.[f]?.active===false?'Inativo':db.fillingSettings?.[f]?.available===false?'Ativo · Indisponível':'Ativo · Disponível'} · ${db.fillingSettings?.[f]?.hasAdditional===false?'Sem adicional':money(db.fillingPrices?.[f]||0)}</p><button class="plain" onclick="editFilling(${i})">Editar recheio</button><button class="soft" onclick="toggleFilling(${i})">${db.fillingSettings?.[f]?.available===false?'Disponibilizar':'Marcar indisponível'}</button></section>`).join('')}</div>`}
function editFilling(index){const name=db.fillings[index]||'',r=db.fillingSettings?.[name]||{};modal(`<div class="dialog-head"><h2>${index<0?'Cadastrar':'Editar'} recheio</h2><button onclick="$('#modal').close()">✕</button></div><form onsubmit="saveFilling(event,${index})"><div class="field-group"><label>Nome do recheio</label><input name="fillingName" value="${esc(name)}" maxlength="80" required ></div><label><input type="checkbox" name="active" style="width:auto" ${r.active!==false?'checked':''}> Ativo na loja</label><label><input type="checkbox" name="available" style="width:auto" ${r.available!==false?'checked':''}> Disponível para compra</label><label><input type="checkbox" name="hasAdditional" style="width:auto" ${r.hasAdditional!==false?'checked':''}> Cobrar adicional deste recheio</label><div class="field-group"><label>Adicional padrão (R$)</label><input name="price" type="number" min="0" step="0.01" value="${db.fillingPrices?.[name]||0}" required></div><button class="primary">Salvar recheio</button></form>`)}
async function saveFilling(e,index){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements,name=f.fillingName.value.trim(),old=db.fillings[index];if(db.fillings.some((n,i)=>i!==index&&n.toLowerCase()===name.toLowerCase()))throw Error('Recheio já cadastrado');const renamed=index>=0&&old!==name,prices={...db.fillingPrices,[name]:Number(f.price.value)},settings={...db.fillingSettings,[name]:{active:f.active.checked,available:f.available.checked,hasAdditional:f.hasAdditional.checked}};if(renamed){delete prices[old];delete settings[old]}const products=db.products.map(p=>{if(!renamed||!p.orderConfig?.fillingOptions?.[old])return p;const options={...p.orderConfig.fillingOptions,[name]:p.orderConfig.fillingOptions[old]};delete options[old];return {...p,orderConfig:{...p.orderConfig,fillingOptions:options}}});await persistTenant({...db,products,fillings:index<0?[...db.fillings,name]:db.fillings.map((n,i)=>i===index?name:n),fillingPrices:prices,fillingSettings:settings},renamed?{fillingRename:{from:old,to:name}}:{});$('#modal').close();render();toast('Recheio salvo')})}

async function toggleFilling(index){const name=db.fillings[index],r=db.fillingSettings?.[name]||{};try{await persistTenant({...db,fillingSettings:{...db.fillingSettings,[name]:{...r,available:r.available===false}}});render()}catch(e){toast(e.message)}}
function productPricingFields(p,c){const sizes=productSizes(p);return `<section class="product-pricing"><h2>Preços por tamanho e acréscimos</h2><p class="muted">Os tamanhos próprios acima substituem os tamanhos compartilhados. Após criar tamanhos, salve e reabra para configurar seus adicionais.</p><button type="button" class="plain" onclick="openSharedPrices('${p.id}')">Editar tamanhos e preços compartilhados</button><div class="form-grid">${[['included','Recheios incluídos',c.included??db.rules.included],['max_selected','Máximo de recheios adicionais além dos incluídos',c.max_selected??Math.max(0,6-(c.included??db.rules.included))],['extra','Cada recheio excedente (R$)',c.extra??db.rules.extra],['floor','Cada andar adicional (R$)',c.floor??db.rules.floor],['topperPrice','Topo personalizado (R$)',c.topperPrice??db.rules.topper]].map(([k,l,v])=>`<div class="field-group"><label>${l}</label><input name="rule_${k}" type="number" min="0" ${['included','max_selected'].includes(k)?'max="30" step="1"':'step="0.01"'} value="${v}" required></div>`).join('')}</div><label><input type="checkbox" name="quantityExtraEnabled" style="width:auto" ${(c.quantityExtraEnabled??db.rules.quantityExtraEnabled)!==false?'checked':''}> Cobrar por recheios além dos incluídos</label><h3>Adicional por recheio excedente em cada tamanho</h3><p>Vazio utiliza o valor do produto.</p>${sizes.map((s,i)=>`<div class="field-group"><label>${esc(s.name)} (R$)</label><input name="extraSize${i}" type="number" min="0" step="0.01" value="${c.extraBySize?.[s.id]??''}"></div>`).join('')}<h3>Recheios vinculados a este produto</h3><p>Valores vazios usam o padrão do recheio. O valor por tamanho tem prioridade.</p>${db.fillings.map((name,i)=>{const r=c.fillingOptions?.[name]||{};return `<fieldset><legend>${esc(name)}</legend><label><input name="useFilling${i}" type="checkbox" style="width:auto" ${r.enabled!==false?'checked':''}> Oferecer neste produto</label><div class="field-group"><label>Adicional neste produto (R$)</label><input name="premium${i}" type="number" step="0.01" min="0" value="${r.price??''}"></div><div class="form-grid">${sizes.map((s,j)=>`<div class="field-group"><label>${esc(s.name)} (R$)</label><input name="premium${i}_${j}" type="number" min="0" step="0.01" value="${r.bySize?.[s.id]??''}"></div>`).join('')}</div></fieldset>`}).join('')}</section>`}
function productPricingValues(f,p){const out={...productConfig(p),quantityExtraEnabled:f.quantityExtraEnabled.checked,extraBySize:{},fillingOptions:{}};for(const k of ['included','max_selected','extra','floor','topperPrice'])out[k]=Number(f['rule_'+k].value);productSizes(p).forEach((s,i)=>{if(f['extraSize'+i].value!=='')out.extraBySize[s.id]=Number(f['extraSize'+i].value)});db.fillings.forEach((name,i)=>{const r={enabled:f['useFilling'+i].checked,bySize:{}};if(f['premium'+i].value!=='')r.price=Number(f['premium'+i].value);productSizes(p).forEach((s,j)=>{if(f['premium'+i+'_'+j].value!=='')r.bySize[s.id]=Number(f['premium'+i+'_'+j].value)});out.fillingOptions[name]=r});return out}
function openSharedPrices(id){modal(`<div class="dialog-head"><h2>Tamanhos e padrões compartilhados</h2><button onclick="configureProduct('${id}')">Voltar às regras</button></div>${prices().replace('savePrices(event)',"saveSharedPrices(event,'"+id+"')").replace('addSize()',"addSharedSize('"+id+"')").replaceAll('removeSize(',"removeSharedSize('"+id+"',")}`)}
function logisticsFields(c){return `<h2>Logística e instruções por etapa</h2><div class="form-grid"><div class="field-group"><label>Atendimento</label><select class="field" name="serviceMode"><option value="both">Entrega + Retirada</option><option value="pickup" ${c.serviceMode==='pickup'?'selected':''}>Apenas Retirada</option></select></div><div class="field-group"><label>Horário inicial</label><input name="openTime" type="time" value="${esc(c.openTime||'08:00')}" required></div><div class="field-group"><label>Horário final</label><input name="closeTime" type="time" value="${esc(c.closeTime||'18:00')}" required></div></div>${checkoutStages.map((stage,i)=>`<div class="field-group"><label>Texto fixo · ${stage}</label><textarea name="instruction${i}" maxlength="2000">${esc(c.instructions?.[stage]||'')}</textarea></div>`).join('')}`}
function logisticsValues(f){return {serviceMode:f.serviceMode.value,openTime:f.openTime.value,closeTime:f.closeTime.value,instructions:Object.fromEntries(checkoutStages.map((s,i)=>[s,f['instruction'+i].value]))}}
async function uploadItemReference(input){const draft=itemDraft;if(!draft||!input.files[0])return;draft.imageUploading=true;try{draft.themeImage=await optimizeStoreImage(input.files[0]);toast('Imagem anexada a este item')}catch(e){toast(e.message)}finally{draft.imageUploading=false;if(itemDraft===draft)renderShop()}}
async function saveSharedPrices(e,id){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements,rules={...db.rules},sizes=db.sizes.map((s,i)=>({...s,name:f['size'+i].value,serves:f['serves'+i].value,price:Number(f['price'+i].value)})),fillingPrices={...db.fillingPrices};for(const k of ['included','extra','floor','topper'])rules[k]=Number(f[k].value);for(const k of ['quantityExtraEnabled','topperAvailable','premiumMinimum'])if(f[k])rules[k]=f[k].checked;db.fillings.forEach((n,i)=>{if(f['fillingPrice'+i])fillingPrices[n]=Number(f['fillingPrice'+i].value)});await persistTenant({...db,sizes,rules,fillingPrices});render();configureProduct(id);toast('Preços compartilhados atualizados')})}
async function removeSharedSize(id,index){if(db.sizes.length===1)return toast('Mantenha ao menos um tamanho');try{await persistTenant({...db,sizes:db.sizes.filter((_,i)=>i!==index)});render();openSharedPrices(id)}catch(e){toast(e.message)}}
function addSharedSize(id){modal(`<div class="dialog-head"><h2>Adicionar tamanho compartilhado</h2><button onclick="openSharedPrices('${id}')">Voltar</button></div><form onsubmit="saveSharedSize(event,'${id}')"><div class="field-group"><label>Tamanho</label><input name="sizeName" maxlength="80" required></div><div class="field-group"><label>Rendimento</label><input name="serves" maxlength="100" required></div><div class="field-group"><label>Preço base (R$)</label><input name="price" type="number" min="0" step="0.01" required></div><button class="primary">Adicionar tamanho</button></form>`)}
async function saveSharedSize(e,id){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements;await persistTenant({...db,sizes:[...db.sizes,{id:crypto.randomUUID(),name:f.sizeName.value,serves:f.serves.value,price:Number(f.price.value)}]});render();openSharedPrices(id)})}
const orderStages=['Novo','Aceito','Em Produção','Finalizado','Entregue','Cancelado'];
const stageMessages={Novo:'Olá, {nome}! Recebemos o pedido #{pedido}.',Aceito:'Olá, {nome}! Seu pedido #{pedido} foi aceito.','Em Produção':'Olá, {nome}! Seu pedido #{pedido} entrou em produção.',Finalizado:'Olá, {nome}! Seu pedido #{pedido} está pronto para retirada/entrega.',Entregue:'Olá, {nome}! Seu pedido #{pedido} foi entregue. Obrigado!',Cancelado:'Olá, {nome}. Seu pedido #{pedido} foi cancelado.'};
let cart=[],cartOwner=null,itemDraft=null,itemStep=0,storeScreen='catalog',checkoutDraft={},cartRequest=null,agendaMonth=today().slice(0,7),agendaDay='',agendaStatus='';
function productConfig(p){return p.orderConfig||{type:'cake',theme:true,fillings:true,floors:true,topper:true,fields:[],sizes:[]}}
function productSizes(p){const c=productConfig(p);return c.sizes?.length?c.sizes:c.type==='cake'?db.sizes:[]}
function allRecipeSizes(){return [...new Map([...db.sizes,...db.products.flatMap(p=>p.orderConfig?.sizes||[]),{id:'unit',name:'Unidade / lote',serves:''}].map(s=>[s.id,s])).values()]}
function recipeSizesFor(kind,subject){if(kind==='filling')return db.sizes;const p=db.products.find(p=>String(p.id)===String(subject));const sizes=p?productSizes(p):[];return sizes.length?sizes:[{id:'unit',name:'Unidade / lote'}]}
function refreshRecipeSizes(subject,kind){$('#modal select[name=sizeId]').innerHTML=recipeSizesFor(kind,subject).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}
function productPrice(p){return productConfig(p).type==='cake'?productSizes(p)[0].price+p.price-(db.rules.reference??65):productSizes(p)[0]?.price??p.price}
const previousProducts=products;products=function(){return heading('Produtos e serviços','Configure o que cada cliente precisa informar.',`<div class="product-heading-actions"><button class="plain" onclick="productClassesModal()">Classes de produto</button><button class="primary" onclick="editProduct()">+ Adicionar produto</button></div>`).replace('class="heading"','class="heading product-management-heading"')+`${productClassToolbar()}<div class="products admin-products">${filteredClassProducts().map(p=>`<article class="card product"><div class="product-img">${p.photo?image(p):'<div class="generic-product">◇</div>'}</div><div class="product-body">${productClassBadge(p)}<h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><strong>${money(productPrice(p))}</strong><div class="dialog-actions"><button class="plain" onclick="editProduct('${p.id}')">Editar</button><button class="soft" onclick="configureProduct('${p.id}')">Perguntas e regras</button><button class="plain" onclick="openProductSizes('${p.id}')">Tamanhos e preços</button><button class="plain" onclick="deleteProduct('${p.id}')">Excluir</button>${productStatusControls(p)}</div></div></article>`).join('')}</div>`};
const previousEditProduct=editProduct;editProduct=function(id){previousEditProduct(id);const h=$('#modal');h.innerHTML=h.innerHTML.replaceAll('Nome do bolo','Nome do produto').replaceAll('Foto do bolo','Foto do produto').replaceAll('Editar bolo','Editar produto').replaceAll('Um novo sabor','Novo produto').replaceAll('Salvar bolo','Salvar produto');const current=db.products.find(p=>String(p.id)===String(id));h.innerHTML=h.innerHTML.replace('<div class="field-group"><label>Descrição</label>',productClassField(current?.classId||'')+'<div class="field-group"><label>Descrição</label>');if(!id){h.innerHTML=h.innerHTML.replace('<div class="field-group"><label>Nome do produto</label>',`<div class="field-group"><label for="copy-product-from">Copiar de</label><select id="copy-product-from" class="field" name="copyFrom" onchange="applyProductCopy(this)"><option value="">Não copiar · começar do zero</option>${db.products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><small>Reaproveita perguntas, tamanhos, adicionais e regras. Ajuste o nome, a descrição, o preço e escolha a imagem do novo produto.</small></div><div class="field-group"><label>Nome do produto</label>`)}};
function applyProductCopy(select){const p=db.products.find(p=>String(p.id)===select.value);if(!p)return;const f=select.form.elements;f.namedItem('name').value=p.name+' (cópia)';f.desc.value=p.desc;f.price.value=p.price;if(f.productClass)f.productClass.value=p.classId||''}

// Preserve the per-product configuration when the basic product editor saves.
saveProduct=async function(e,id){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements,old=db.products.find(p=>String(p.id)===String(id)),source=!id&&f.copyFrom?.value?db.products.find(p=>String(p.id)===f.copyFrom.value):null;if(!id&&f.copyFrom?.value&&!source)throw Error('O produto de origem não está mais disponível');const template=source?structuredClone(source):{};const p={...template,...old,...(source?{active:true,available:true}:{}),id:id||crypto.randomUUID(),classId:f.productClass?.value??old?.classId??source?.classId??'',name:f.namedItem('name').value,desc:f.desc.value,price:Number(f.price.value),photo:old?.photo||'',color:old?.color||source?.color||'#e9a9bf'};if(f.photo.files[0])p.photo=await optimizeStoreImage(f.photo.files[0]);await persistTenant({...db,products:old?db.products.map(row=>row===old?p:row):[...db.products,p]});$('#modal').close();render();toast('Produto salvo')})};
function configureProduct(id){const p=db.products.find(p=>String(p.id)===id),c=productConfig(p);modal(`<div class="dialog-head"><h2>Perguntas e regras · ${esc(p.name)}</h2><button onclick="$('#modal').close()">✕</button></div><form onsubmit="saveProductConfig(event,'${id}')"><div class="field-group"><label>Modelo de compra</label><select class="field" name="type">${[['cake','Bolo personalizado'],['simple','Produto simples / unidade'],['sweets','Doces por lote / cento'],['custom','Personalizado: camisa, caneca, torta…']].map(([v,l])=>`<option value="${v}" ${v===c.type?'selected':''}>${l}</option>`).join('')}</select></div><p class="muted">Produtos simples não perguntam recheio, andares ou topo. Para tortas, use personalizado com tamanhos próprios.</p><div class="form-grid">${[['theme','Pedir tema / personalização'],['fillings','Pedir recheios (bolo)'],['floors','Pedir andares (bolo)'],['topper','Pedir topo (bolo)']].map(([k,l])=>`<label><input style="width:auto" type="checkbox" name="${k}" ${c[k]?'checked':''}> ${l}</label>`).join('')}</div><div class="field-group"><label>Tamanhos próprios: nome | rendimento | preço (uma linha por tamanho)</label><textarea name="sizes" placeholder="P | 10 a 15 fatias | 90&#10;M | 20 a 25 fatias | 150">${esc((c.sizes||[]).map(s=>s.name+' | '+s.serves+' | '+s.price).join('\n'))}</textarea><small>No modelo bolo, vazio usa os tamanhos de Preços. Nos outros modelos, vazio vende por unidade ao preço do produto.</small></div><div class="form-grid"><div class="field-group"><label>Unidades por lote (doces)</label><input type="number" name="pack" value="${c.pack||100}" min="1"></div><div class="field-group"><label>Múltiplo e mínimo por sabor</label><input type="number" name="increment" value="${c.increment||25}" min="1"></div><div class="field-group"><label>Máximo de sabores por lote</label><input type="number" name="maxFlavors" value="${c.maxFlavors||4}" min="1" max="30"></div><div class="field-group"><label>Antecedência mínima (dias corridos)</label><input type="number" name="leadDays" value="${c.leadDays||0}" min="0" max="365"></div></div><div class="field-group"><label>Sabores dos doces (um por linha)</label><textarea name="flavors">${esc((c.flavors||[]).join('\n'))}</textarea></div><div class="field-group"><label>Perguntas adicionais: pergunta | obrigatório ou opcional | opções separadas por vírgula</label><textarea name="fields" placeholder="Texto da estampa | obrigatório&#10;Cor | obrigatório | Branco, Preto, Azul">${esc((c.fields||[]).map(f=>f.label+' | '+(f.required?'obrigatório':'opcional')+(f.type==='select'?' | '+f.options.join(', '):'')).join('\n'))}</textarea></div><div class="field-group"><label>Guia / instruções do produto</label><textarea name="guide" maxlength="3000">${esc(c.guide||'')}</textarea></div><div class="field-group"><label>Condições de pagamento (substitui o texto geral neste item)</label><textarea name="payment" maxlength="2000" placeholder="50% para reserva; restante na retirada.">${esc(c.payment||'')}</textarea></div>${productPricingFields(p,c)}<button class="primary">Salvar perguntas e regras</button></form>`)}
async function saveProductConfig(e,id){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements,p=db.products.find(p=>String(p.id)===id),old=p.orderConfig,lines=v=>v.split('\n').map(s=>s.trim()).filter(Boolean);const sizes=lines(f.sizes.value).map((line,i)=>{const [name,serves,raw]=line.split('|').map(s=>s.trim());return {id:old?.sizes?.[i]?.id||crypto.randomUUID(),name,serves:serves||'',price:Number(raw?.replace(',','.'))}});const fields=lines(f.fields.value).map((line,i)=>{const [label,required,opts]=line.split('|').map(s=>s.trim());return {id:old?.fields?.[i]?.id||'q-'+crypto.randomUUID(),label,required:required?.toLowerCase()==='obrigatório',type:opts?'select':'text',options:opts?opts.split(',').map(s=>s.trim()).filter(Boolean):[]}});const next={...db,products:db.products.map(product=>String(product.id)===id?{...product,orderConfig:{...productPricingValues(f,p),type:f.type.value,theme:f.theme.checked,fillings:f.fillings.checked,floors:f.floors.checked,topper:f.topper.checked,sizes,fields,guide:f.guide.value,payment:f.payment.value,leadDays:Number(f.leadDays.value),pack:Number(f.pack.value),increment:Number(f.increment.value),maxFlavors:Number(f.maxFlavors.value),flavors:lines(f.flavors.value)}}:product)};await persistTenant(next);$('#modal').close();render();toast('Perguntas do produto atualizadas')})}
const customizeBeforeCommerce=customizationPage;customizationPage=function(){const c=db.commerce||{};return customizeBeforeCommerce().replace('montar o bolo','fazer encomendas')+`<form class="card" style="margin-top:20px" onsubmit="saveCommerceSettings(event)"><h2>Segmento, prazos e atendimento</h2><div class="field-group"><label>Segmento da loja</label><input name="segment" maxlength="80" value="${esc(c.segment||'Encomendas')}" placeholder="Salgados, personalizados, confeitaria…"></div><div class="field-group"><label>Antecedência mínima geral (dias corridos)</label><input name="leadDays" type="number" min="0" max="365" value="${c.leadDays||0}"></div><div class="field-group"><label>Texto geral de pagamento e garantia</label><textarea name="payment" maxlength="2000">${esc(c.payment||'')}</textarea></div>${logisticsFields(c)}<h2>Mensagens de status</h2><p class="muted">Preparadas para envio manual no WhatsApp. Variáveis: {nome}, {pedido}, {status}, {link}, {data}, {horario}. Deixe vazio para desabilitar uma mensagem.</p>${orderStages.map((s,i)=>`<div class="field-group"><label>${s}</label><textarea name="message${i}" maxlength="1500">${esc(c.messages?.[s]??stageMessages[s])}</textarea></div>`).join('')}<button class="primary">Salvar regras e mensagens</button></form>`};
async function saveCommerceSettings(e){e.preventDefault();await submitForm(e.target,async()=>{const f=e.target.elements;await persistTenant({...db,commerce:{...db.commerce,...logisticsValues(f),segment:f.segment.value,leadDays:Number(f.leadDays.value),payment:f.payment.value,messages:Object.fromEntries(orderStages.map((s,i)=>[s,f['message'+i].value]))}});render();toast('Regras e mensagens salvas')})}
function syncCartStore(){if(cartOwner!==platform.active){cart=[];checkoutDraft={};cartRequest=null;itemDraft=null;storeScreen='catalog';cartOwner=platform.active}}
function startItem(id,index=-1){const p=db.products.find(p=>String(p.id)===String(id)),c=productConfig(p);if(p.active===false||p.available===false)return toast('Produto indisponível');itemDraft=index>=0?structuredClone(cart[index]):{product:String(p.id),quantity:1,size:productSizes(p)[0]?.id||'',fill:[],floors:1,topper:false,theme:'',flavors:{},answers:{}};itemDraft.editIndex=index;itemStep=0;storeScreen='item';renderShop()}
function checkoutFields(){return `<h3>Agende sua entrega ou retirada</h3>${instructionBlock('Finalização')}<div class="checkout-schedule-fields"><div class="field-group"><label>Data de entrega / retirada</label>${deliveryDatePicker()}<p class="muted">Primeira data permitida: ${date(minimumDelivery())}.</p></div><div class="field-group"><label>Horário de retirada / entrega solicitado</label><input name="pickupTime" type="time" min="${esc(db.commerce?.openTime||'08:00')}" max="${esc(db.commerce?.closeTime||'18:00')}" value="${esc(checkoutDraft.pickupTime||'')}" required><small>Horário sujeito à confirmação do estabelecimento.</small></div><div class="field-group"><label>Nome do solicitante</label><input name="customerName" value="${esc(checkoutDraft.name||'')}" maxlength="150" autocomplete="name" required></div><div class="field-group"><label>Seu WhatsApp (DDD + número)</label><div class="phone-field"><span>+55</span><input name="customerPhone" type="tel" autocomplete="tel-national" placeholder="11999999999" value="${esc((checkoutDraft.customerPhone||'').replace(/^55(?=\d{10,11}$)/,''))}" required></div></div><div class="field-group"><label>Tipo de atendimento</label><select name="fulfillment" class="field" onchange="checkoutDraft.fulfillment=this.value;const a=this.form.elements.address;a.required=this.value==='delivery';a.closest('.field-group').hidden=this.value!=='delivery'"><option value="pickup">Retirada</option>${db.commerce?.serviceMode==='pickup'?'':`<option value="delivery" ${checkoutDraft.fulfillment==='delivery'?'selected':''}>Entrega</option>`}</select></div><div class="field-group" ${checkoutDraft.fulfillment!=='delivery'?'hidden':''}><label>Endereço de entrega</label><input name="address" maxlength="500" value="${esc(checkoutDraft.address||'')}" ${checkoutDraft.fulfillment==='delivery'?'required':''}></div><div class="field-group"><label>Observações</label><textarea name="notes" maxlength="3000">${esc(checkoutDraft.notes||'')}</textarea></div></div>`}

function checkoutSummary(editable=true){return `<section class="checkout-summary"><h2>Dados e agendamento</h2><p>${esc(checkoutDraft.name||'Dados ainda não informados')} · ${esc(checkoutDraft.customerPhone||'')}</p><p>${checkoutDraft.delivery?date(checkoutDraft.delivery):'Escolha uma data'} · ${esc(checkoutDraft.pickupTime||'Sem horário')}</p><p>${checkoutDraft.fulfillment==='delivery'?'Entrega: '+esc(checkoutDraft.address||''):'Retirada no estabelecimento'}</p>${editable?'<button class="plain" type="button" onclick="editCartSchedule()">Alterar dados e agendamento</button>':''}</section>`}
function editCartSchedule(){if(!cart.length)return;startItem(cart[0].product,0);if(itemDraft){itemStep=itemSteps().indexOf('Agendamento');renderShop()}}
function itemSteps(){const p=db.products.find(p=>String(p.id)===itemDraft.product),c=productConfig(p);return ['Definição',...(c.type==='cake'&&c.fillings!==false?['Recheios']:[]),...(c.type==='sweets'?['Sabores']:[]),...((c.theme||c.type==='cake'&&(c.floors!==false||c.topper!==false))?['Personalização']:[]),...((c.fields||[]).length?['Perguntas']:[]),'Agendamento']}
function itemFields(){const p=db.products.find(p=>String(p.id)===itemDraft.product),c=productConfig(p),step=itemSteps()[itemStep],v=itemDraft;if(step==='Definição')return `<div class="field-group"><label>${c.type==='sweets'?'Quantidade de lotes de '+c.pack+' unidades':'Quantidade'}</label><input name="quantity" type="number" min="1" max="100" value="${v.quantity}" required oninput="itemDraft.quantity=Number(this.value);updateItemSubtotal()"></div>${productSizes(p).length?sizeChoice(p,v):''}`;if(step==='Tamanho')return `<label>Tamanho</label><select class="field" name="size">${productSizes(p).map(s=>`<option value="${esc(s.id)}" ${s.id===v.size?'selected':''}>${esc(s.name)} · ${esc(s.serves)} · ${money(c.type==='cake'?s.price+p.price-(db.rules.reference??65):s.price)}</option>`).join('')}</select>`;if(step==='Recheios')return fillingChoices(p,v);if(step==='Sabores')return `<p>Distribua ${c.pack} unidades por lote, até ${c.maxFlavors} sabores, em múltiplos de ${c.increment}. Quantidade de lotes: ${v.quantity}.</p>${c.flavors.map((f,i)=>`<div class="field-group"><label>${esc(f)}</label><input name="flavor${i}" type="number" min="0" step="${c.increment}" max="${c.pack}" value="${v.flavors[f]||0}"></div>`).join('')}`;if(step==='Personalização')return (c.theme?`<div class="field-group"><label>Tema / personalização desejada</label><input name="theme" oninput="itemDraft.theme=this.value" ${v.alignModel?'':'required'} placeholder="Escolha um tema ou digite Sem tema" maxlength="200" value="${esc(v.theme)}" list="theme-options"><datalist id="theme-options">${(db.themes||[]).map(t=>`<option value="${esc(t.name)}">`).join('')}</datalist></div><button class="soft" type="button" onclick="itemDraft.alignModel=!itemDraft.alignModel;renderShop()" aria-pressed="${v.alignModel===true}">${v.alignModel?'✓ Modelo será alinhado com a empresa':'Alinhar o modelo diretamente com a empresa'}</button><div class="field-group"><label>Imagem de referência deste item</label><input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadItemReference(this)">${v.themeImage?'<p>✓ Imagem anexada</p><button class="plain" type="button" onclick="itemDraft.themeImage=undefined;renderShop()">Remover imagem</button>':''}</div>`:``)+(c.type==='cake'?`${c.floors!==false?`<div class="field-group"><label>Andares</label><select name="floors" class="field" onchange="itemDraft.floors=Number(this.value);updateItemSubtotal()">${[1,2,3].map(n=>`<option ${n===v.floors?'selected':''}>${n}</option>`).join('')}</select><small>Adicional por andar extra: ${money(c.floor??db.rules.floor)}</small></div>`:''}${c.topper!==false&&db.rules.topperAvailable!==false?`<label><input type="checkbox" name="topper" onchange="itemDraft.topper=this.checked;updateItemSubtotal()" style="width:auto" ${v.topper?'checked':''}> Topo personalizado (${db.rules.topperMinimum?'a partir de ':'+ '}${money(c.topperPrice??db.rules.topper)})</label>`:''}`:``);if(step==='Agendamento')return checkoutFields();if(step==='Perguntas')return (c.fields||[]).map(f=>`<div class="field-group"><label>${esc(f.label)}${f.required?' *':''}</label>${f.type==='select'?`<select class="field" name="${f.id}" ${f.required?'required':''}><option value="">Selecione</option>${f.options.map(o=>`<option ${v.answers[f.id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="${f.id}" value="${esc(v.answers[f.id]||'')}" maxlength="1000" ${f.required?'required':''}>`}</div>`).join('');return `<h3>${esc(p.name)}</h3><p>${v.quantity} × ${esc(productSizes(p).find(s=>s.id===v.size)?.name||'Unidade')}</p><p>${esc(v.fill.join(', '))}${v.theme?' · '+esc(v.theme):''}${v.topper?' · Com topo personalizado':''}</p>${checkoutSummary(false)}<p>Confira as opções e adicione o item ao carrinho.</p>${c.payment||db.commerce?.payment?`<div class="note preserve-lines">${esc(c.payment||db.commerce.payment)}</div>`:''}`}

function advanceItem(e){e.preventDefault();const f=e.target.elements,p=db.products.find(p=>String(p.id)===itemDraft.product),c=productConfig(p),step=itemSteps()[itemStep];if(itemDraft.imageUploading)return toast('Aguarde o carregamento da imagem');if(f.itemNotes)itemDraft.notes=f.itemNotes.value;if(step==='Definição'){const q=Number(f.quantity.value);if(!Number.isInteger(q)||q<1||q>100)return toast('Informe uma quantidade de 1 a 100');itemDraft.quantity=q;if(f.size)itemDraft.size=f.size.value}if(step==='Tamanho')itemDraft.size=f.size.value;if(step==='Recheios'){itemDraft.fill=[...e.target.querySelectorAll('[name=fill]:checked')].map(n=>n.value);if(!itemDraft.fill.length||itemDraft.fill.length>fillingLimit(p))return toast('Escolha de 1 a '+fillingLimit(p)+' recheios')}if(step==='Sabores'){itemDraft.flavors=Object.fromEntries(c.flavors.map((s,i)=>[s,Number(f['flavor'+i].value)]).filter(([,n])=>n));const values=Object.values(itemDraft.flavors);if(values.length>c.maxFlavors||values.some(n=>n<c.increment||n%c.increment)||values.reduce((a,b)=>a+b,0)!==c.pack)return toast('Distribua '+c.pack+' unidades respeitando o limite de sabores e os múltiplos de '+c.increment)}if(step==='Personalização'){if(c.theme&&!itemDraft.alignModel&&!f.theme.value.trim())return toast('Escolha um tema ou informe Sem tema');itemDraft.theme=c.theme?(itemDraft.alignModel?'Alinhar o modelo diretamente com a empresa':f.theme.value.trim()):'';itemDraft.floors=Number(f.floors?.value||1);itemDraft.topper=f.topper?.checked||false}if(step==='Agendamento'){readCheckoutFields(f);try{validateCheckoutDraft()}catch(error){return toast(error.message)}}if(step==='Perguntas')for(const q of c.fields)itemDraft.answers[q.id]=f[q.id].value;if(step==='Agendamento'){if(itemDraft.editIndex>=0)cart[itemDraft.editIndex]={...itemDraft};else cart.push({...itemDraft});storeScreen='cart';cartRequest=null;itemDraft=null}else itemStep++;renderShop()}
function cartLineValue(i){const p=db.products.find(p=>String(p.id)===String(i.product)),c=productConfig(p);if(c.type!=='cake')return (productSizes(p).find(s=>s.id===i.size)?.price??p.price)*i.quantity;const s=productSizes(p).find(s=>s.id===i.size)||productSizes(p)[0],premium=i.fill.reduce((sum,f)=>sum+fillingAmount(p,f,i.size),0),extra=c.extraBySize?.[i.size]??c.extra??db.rules.extra;return (s.price+p.price-(db.rules.reference??65)+premium+((c.quantityExtraEnabled??db.rules.quantityExtraEnabled)===false?0:Math.max(0,i.fill.length-(c.included??db.rules.included))*extra)+(i.floors-1)*(c.floor??db.rules.floor)+(i.topper?(c.topperPrice??db.rules.topper):0))*i.quantity}

function cartSummary(){return cart.map((i,n)=>{const p=db.products.find(p=>String(p.id)===i.product);return `<section class="cart-line"><h3>${i.quantity} × ${esc(p.name)}</h3><p>${esc(productSizes(p).find(s=>s.id===i.size)?.name||'')}${i.fill.length?' · '+esc(i.fill.join(', ')):''}${i.theme?' · '+esc(i.theme):''}</p>${Object.entries(i.flavors||{}).map(([f,q])=>`<small>${esc(f)}: ${q*i.quantity} un. </small>`).join('')}<strong>${money(cartLineValue(i))}</strong>${productConfig(p).payment&&productConfig(p).payment.trim()!==(db.commerce?.payment||'').trim()?`<p class="note preserve-lines">${esc(productConfig(p).payment)}</p>`:''}<div><button class="plain" onclick="startItem('${i.product}',${n})">Editar</button><button class="plain" onclick="cart.splice(${n},1);cartRequest=null;renderShop()">Remover</button></div></section>`}).join('')+`<div class="total"><span>Total${(db.rules.premiumMinimum||db.rules.topperMinimum&&cart.some(i=>i.topper))?' estimado':''}</span><strong>${money(cart.reduce((s,i)=>s+cartLineValue(i),0))}</strong></div>`}
function minimumDelivery(){let days=db.commerce?.leadDays||0;for(const i of [...cart,...(storeScreen==='item'&&itemDraft?[itemDraft]:[])])days=Math.max(days,productConfig(db.products.find(p=>String(p.id)===i.product)).leadDays||0);const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+days);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
renderShop=function(){if(!licenseValid())return renderBlocked();syncCartStore();const s=db.store||{};let content;if(storeScreen==='catalog')content=`<div class="heading"><div><h2>Escolha seus produtos</h2><p>Adicione um ou mais itens à sua encomenda.</p></div><button class="primary" onclick="storeScreen='cart';renderShop()">Carrinho (${cart.length})</button></div><div class="products">${db.products.filter(p=>p.active!==false).map(p=>`<article class="card product"><div class="product-img">${p.photo?image(p):'<div class="generic-product">◇</div>'}</div><div class="product-body"><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><strong>A partir de ${money(productPrice(p))}</strong><button class="primary" ${p.available===false?'disabled':''} onclick="startItem('${p.id}')">${p.available===false?'Indisponível':'Escolher opções →'}</button></div></article>`).join('')}</div>`;else if(storeScreen==='item'){const p=db.products.find(p=>String(p.id)===itemDraft.product),steps=itemSteps();content=`<form class="card item-config ${steps[itemStep]==='Agendamento'?'checkout-form':''}" ${steps[itemStep]==='Agendamento'?'oninput="rememberCheckout()" onchange="rememberCheckout()"':''} onsubmit="advanceItem(event)"><span class="eyebrow">${esc(p.name)}</span><div class="wizard-progress-head"><span>Etapa ${itemStep+1} de ${steps.length}</span><b>${steps[itemStep]}</b></div><div class="wizard-progress" role="progressbar" aria-label="Progresso do item" aria-valuemin="0" aria-valuemax="${steps.length}" aria-valuenow="${itemStep+1}"><span style="width:${(itemStep+1)/steps.length*100}%"></span></div><h2>${steps[itemStep]}</h2>${productConfig(p).guide?`<p class="note preserve-lines">${esc(productConfig(p).guide)}</p>`:''}${instructionBlock(steps[itemStep])}${steps[itemStep]==='Personalização'?instructionBlock('Detalhes'):''}${itemFields()}<div class="field-group"><label>Observações deste item</label><textarea name="itemNotes" maxlength="3000" oninput="itemDraft.notes=this.value">${esc(itemDraft.notes||'')}</textarea></div><div class="total"><span>Subtotal do item</span><strong>${money(cartLineValue(itemDraft))}</strong></div><div class="dialog-actions"><button class="plain" type="button" onclick="if(itemStep>0)itemStep--;else storeScreen='catalog';renderShop()">← Voltar</button><button class="primary">${itemStep===steps.length-1?(itemDraft.editIndex>=0?'Salvar alterações':'Adicionar ao carrinho'):'Continuar →'}</button></div></form>`}else content=`<section class="card"><h2>Seu carrinho</h2>${instructionBlock('Revisão')}${cart.length?cartSummary():'<p>Carrinho vazio. Escolha seus produtos para começar.</p>'}<button class="plain" onclick="storeScreen='catalog';renderShop()">+ Adicionar outro item</button>${cart.length?`<form onsubmit="submitCart(event)" class="checkout-form">${checkoutSummary()}${db.commerce?.payment?`<div class="note preserve-lines">${esc(db.commerce.payment)}</div>`:''}<button class="whatsapp">Fazer pedido pelo WhatsApp →</button></form>`:''}</section>`;$('#app').innerHTML=`<main class="store commerce-store" style="--pink:${esc(s.accent||'#e75c8a')}"><header class="store-header">${brand()}<a class="plain" href="/">Área do estabelecimento</a></header>${s.banner?`<div class="store-banner"><img src="${esc(s.banner)}" alt="Topo da loja"></div>`:''}<div class="wizard-intro"><div class="eyebrow">${esc(s.eyebrow||db.commerce?.segment||'ENCOMENDAS DO SEU JEITO')}</div><h1>${esc(s.title||'Vamos preparar sua encomenda?')}</h1><p>${esc(s.subtitle||'Escolha, personalize e reúna tudo em um único pedido.')}</p>${db.presentation?.notice?`<p class="note preserve-lines">${esc(db.presentation.notice)}</p>`:''}</div><div class="commerce-content">${storeScreen==='catalog'?`<div class="field-group"><label>Observações gerais da encomenda</label><textarea maxlength="3000" oninput="checkoutDraft.notes=this.value">${esc(checkoutDraft.notes||'')}</textarea></div>`:''}${content}</div><footer class="store-footer">${esc(brandText(s.footer)||activeTenant().name+' · Encomendas com EncomendAki')}</footer></main>`};
async function submitCart(e){e.preventDefault();const f=e.target.elements;readCheckoutFields(f);await submitForm(e.target,async()=>{validateCheckoutDraft();let themeImage=checkoutDraft.themeImage;if(f.reference?.files[0]){const file=f.reference.files[0];if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use JPG, PNG ou WebP de até 2 MB');themeImage=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Falha ao ler imagem'));reader.readAsDataURL(file)});checkoutDraft.themeImage=themeImage}const {birthDate,eventType,eventDate,eventName,marketingConsent,...customerDraft}=checkoutDraft;const payload={...customerDraft,themeImage,items:cart.map(({editIndex,...i})=>i),catalogVersion},signature=JSON.stringify(payload);if(cartRequest?.signature!==signature)cartRequest={signature,key:crypto.randomUUID()};const result=await api('/api/public/'+activeTenant().slug+'/orders',{method:'POST',body:{...payload,requestKey:cartRequest.key}});cart=[];$('#app').innerHTML=`<main class="receipt card"><h1>Encomenda registrada!</h1><p>Pedido #${esc(result.order.id.slice(0,8))}. Envie a mensagem para combinar a confirmação com o estabelecimento.</p><div class="total"><span>Total</span><strong>${money(result.order.value)}</strong></div><a class="whatsapp" href="${esc(result.whatsapp)}" target="_blank" rel="noopener">Enviar pedido pelo WhatsApp →</a><p><a href="${esc(result.trackingUrl)}">Acompanhar meu pedido</a></p><button class="plain" onclick="storeScreen='catalog';cartRequest=null;checkoutDraft={};renderShop()">Nova encomenda</button></main>`;window.open(result.whatsapp,'_blank','noopener')})}
const previousAdminContent=adminContent;adminContent=function(){if(page==='Recheios')return fillingsPage();if(page==='Agenda')return agendaPage();if(page==='Kanban')return kanbanPage();return previousAdminContent()};
function agendaOverview(month=agendaMonth){const [year,m]=month.split('-').map(Number),length=new Date(year,m,0).getDate(),orders=db.orders.filter(o=>o.delivery.startsWith(month));const days=Array.from({length},(_,i)=>{const key=month+'-'+String(i+1).padStart(2,'0'),all=orders.filter(o=>o.delivery===key),active=all.filter(o=>o.status!=='Cancelado'),blocked=isDeliveryBlocked(key);return {key,number:i+1,orders:active.length,cancelled:all.length-active.length,filtered:all.filter(o=>!agendaStatus||o.status===agendaStatus).length,blocked,past:key<today(),state:blocked?'blocked':active.length?'occupied':'free'}});return {days,orders:orders.filter(o=>o.status!=='Cancelado').length,occupied:days.filter(d=>d.orders>0).length,blocked:days.filter(d=>d.blocked).length,free:days.filter(d=>d.state==='free'&&!d.past).length}}
function agendaPage(){
 const rows=db.orders.filter(o=>o.delivery.startsWith(agendaMonth)&&(!agendaDay||o.delivery===agendaDay)&&(!agendaStatus||o.status===agendaStatus)).sort((a,b)=>(a.delivery+(a.pickupTime||'99:99')).localeCompare(b.delivery+(b.pickupTime||'99:99')));
 const overview=agendaOverview(),year=Number(agendaMonth.slice(0,4)),month=Number(agendaMonth.slice(5)),offset=new Date(year,month-1,1).getDay();
 return heading('Agenda de encomendas','Veja a ocupação do mês e planeje suas próximas entregas.')+`<div class="toolbar"><input type="month" aria-label="Mês da agenda" value="${agendaMonth}" onchange="agendaMonth=this.value||today().slice(0,7);agendaDay='';render()"><select class="field" aria-label="Status na agenda" onchange="agendaStatus=this.value;render()"><option value="">Todos os status</option>${orderStages.map(s=>`<option ${s===agendaStatus?'selected':''}>${s}</option>`).join('')}</select><button class="plain" onclick="agendaMonth=today().slice(0,7);agendaDay=today();render()">Hoje</button><button class="plain" onclick="agendaDay='';render()">Mês inteiro</button></div><div class="agenda-overview">${[[overview.orders,'Pedidos no mês','occupied'],[overview.occupied,'Dias com pedidos','occupied'],[overview.blocked,'Dias indisponíveis','blocked'],[overview.free,'Dias livres a partir de hoje','free']].map(([value,label,state])=>`<section class="card agenda-stat ${state}"><strong>${value}</strong><span>${label}</span></section>`).join('')}</div><section class="card agenda-calendar"><div class="agenda-legend" aria-label="Legenda da agenda"><span class="occupied">Com pedidos</span><span class="blocked">Indisponível</span><span class="free">Livre</span><span class="today">Hoje</span></div><p class="muted agenda-calendar-note">As cores consideram todas as encomendas não canceladas, mesmo com filtro de status. Um dia bloqueado pode manter pedidos já registrados.</p><div class="calendar-grid agenda-month-grid">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<b>${d}</b>`).join('')}${'<span></span>'.repeat(offset)}${overview.days.map(d=>`<button type="button" class="calendar-day agenda-day agenda-${d.state} ${d.past?'agenda-past':''} ${d.key===today()?'agenda-today':''} ${d.key===agendaDay?'selected':''}" aria-label="${d.key.split('-').reverse().join('/')} · ${d.blocked?'Indisponível':d.orders?'Com pedidos':d.past?'Sem pedidos':'Livre'} · ${d.orders} pedido(s)${d.key===today()?' · Hoje':''}" aria-pressed="${d.key===agendaDay}" onclick="agendaDay='${d.key}';render()"><span class="agenda-day-head"><strong>${d.number}</strong>${d.key===today()?'<em>Hoje</em>':''}</span><span class="agenda-day-label">${d.blocked?'Indisponível':d.orders?'Com pedidos':d.past?'Sem pedidos':'Livre'}</span>${d.orders?`<span class="agenda-order-count">${d.orders} pedido${d.orders===1?'':'s'}</span>`:''}${agendaStatus?`<small>${d.filtered} no filtro</small>`:d.cancelled?`<small>${d.cancelled} cancelado(s)</small>`:''}</button>`).join('')}</div></section>${agendaAvailabilityControls()}<h2 style="margin-top:20px">${agendaDay?date(agendaDay):'Encomendas do mês'}</h2><section class="card">${rows.map(o=>`<div class="agenda-order"><time>${date(o.delivery)} · ${esc(o.pickupTime||'Sem horário')}</time><button class="plain" onclick="orderDetails('${o.id}')">${esc(o.name)} · ${esc(o.product)}</button><b>${esc(o.status)}</b></div>`).join('')||'<p>Nenhuma encomenda neste período.</p>'}</section>`
}
function kanbanPage(){return heading('Kanban de encomendas','Atualize a etapa de cada pedido e prepare a mensagem para o cliente.')+`<div class="kanban">${orderStages.map(s=>`<section class="kanban-column"><h2>${s} <small>${db.orders.filter(o=>o.status===s).length}</small></h2>${db.orders.filter(o=>o.status===s).map(o=>`<article class="card"><button class="plain" onclick="orderDetails('${o.id}')"><strong>${esc(o.name)}</strong></button><p>${esc(o.product)}</p><small>${date(o.delivery)} · ${esc(o.pickupTime||'A combinar')}</small><p><b>${money(o.value)}</b></p><select class="field" aria-label="Etapa do pedido ${o.id}" onchange="changeStatus('${o.id}',this.value)">${orderStages.map(st=>`<option ${st===s?'selected':''}>${st}</option>`).join('')}</select></article>`).join('')}</section>`).join('')}</div>`}
changeStatus=async function(id,status){try{const result=await api('/api/tenants/'+platform.active+'/orders/'+id,{method:'PATCH',body:{status}});db.orders.find(o=>o.id===id).status=status;render();if(result.notification)modal(`<div class="dialog-head"><h2>Status atualizado: ${esc(status)}</h2><button onclick="$('#modal').close()">✕</button></div><p>A mensagem está pronta. Clique para abrir o WhatsApp e enviá-la ao cliente.</p><a class="whatsapp" href="${esc(result.notification.whatsapp)}" target="_blank" rel="noopener">Notificar cliente pelo WhatsApp →</a>`);else toast('Status atualizado. Sem mensagem ou WhatsApp do cliente configurado.')}catch(e){render();toast(e.message)}};
const originalDetails=orderDetails;orderDetails=function(id){const o=db.orders.find(o=>o.id===id);if(!o.items)return originalDetails(id);modal(`<div class="dialog-head"><h2>Pedido #${id.slice(0,8)}</h2><button onclick="$('#modal').close()">✕</button></div><h2>${esc(o.name)}</h2><p>${date(o.delivery)} · ${esc(o.pickupTime||'Horário a combinar')} · ${esc(o.status)}</p>${o.items.map((i,index)=>`<section class="cart-line"><h3>${i.quantity} × ${esc(i.product)} · ${esc(i.size)}</h3><p>${esc(i.filling||'')} ${esc(i.theme||'')}</p>${Object.values(i.answers||{}).map(a=>`<p>${esc(a.label)}: ${esc(a.value)}</p>`).join('')}${i.payment?`<p class="preserve-lines">${esc(i.payment)}</p>`:''}<p class="preserve-lines">${esc(i.notes||'')}</p>${i.hasThemeImage?`<a href="${orderReferenceUrl(id)}?item=${index}" target="_blank" rel="noopener">Ver referência deste item</a>`:''}<b>${money(i.value)}</b></section>`).join('')}<p>Nascimento: ${o.birthDate?date(o.birthDate):'Não informado'} · ${o.fulfillment==='delivery'?'Entrega: '+esc(o.address):'Retirada'}</p><p class="preserve-lines">${esc(o.notes)}</p>${o.hasThemeImage?`<a href="${orderReferenceUrl(id)}" target="_blank" rel="noopener">Ver imagem de referência</a>`:''}<p><a href="/pedido/${o.trackingToken}" target="_blank" rel="noopener">Acompanhamento do pedido</a></p><div class="total">Total <strong>${money(o.value)}</strong></div>`)};
function trackingProgress(status){const stages=orderStages.filter(s=>s!=='Cancelado'),current=stages.indexOf(status),cancelled=status==='Cancelado';return `<div class="tracking-current-status ${cancelled?'is-cancelled':''}" role="status"><span>${cancelled?'Situação do pedido':'Etapa atual do pedido'}</span><strong>${esc(status)}</strong></div>${cancelled?'<p class="tracking-cancel-note">Este pedido foi cancelado. Entre em contato com a loja se precisar de ajuda.</p>':`<ol class="tracking-stages tracking-progress" aria-label="Etapas do pedido">${stages.map((s,i)=>`<li class="${i===current?'current':i<current?'completed':'pending'}" ${i===current?'aria-current="step"':''}><span class="tracking-step-number">${i<current?'✓':i+1}</span><b>${s}</b><small>${i===current?'Etapa atual':i<current?'Concluída':'Próxima etapa'}</small></li>`).join('')}</ol>`}`}
loadTracking=async function(token){try{const {order:o}=await api('/api/tracking/'+token);$('#app').innerHTML=`<main class="tracking-page"><section class="card"><h1>${esc(o.store)}</h1><p>Pedido #${esc(o.number)}</p>${o.storeSlug?`<p><a href="/loja/${esc(o.storeSlug)}">Loja /loja/${esc(o.storeSlug)}</a></p>`:''}${trackingProgress(o.status)}<p>${date(o.delivery)} · ${esc(o.pickupTime||'Horário a combinar')}</p>${o.items?o.items.map(i=>`<p>${i.quantity} × ${esc(i.product)} · ${esc(i.size)}</p>`).join(''):`<p>${esc(o.product)} · ${esc(o.size)}</p>`}<div class="total">Total <strong>${money(o.value)}</strong></div><button class="primary" onclick="loadTracking('${token}')">Atualizar acompanhamento</button><p class="muted">Atualização automática a cada 15 segundos enquanto esta página estiver aberta. Status informado pelo estabelecimento.</p></section></main>`}catch(e){$('#app').innerHTML=`<main class="license-block"><h1>Acompanhamento indisponível</h1><p>${esc(e.message)}</p></main>`}};
